<section x-data="dailyWorkReportData()" id="laporan-harian" class="overflow-hidden rounded-2xl border border-slate-200 bg-white">
    <div class="border-b border-slate-100 p-5 sm:p-7"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-wider text-brand-700">Laporan kerja harian</p><h2 class="mt-2 text-lg font-bold" x-text="dateLabel(date)"></h2><p class="mt-2 text-sm leading-6 text-slate-500">Isi total durasi hari ini dan pilih semua HP yang kamu gunakan.</p></div><span class="rounded-full px-3 py-1.5 text-xs font-semibold" :class="revision?'bg-brand-50 text-brand-700':'bg-amber-50 text-amber-800'" x-text="revision?'Sudah dikirim':'Belum dikirim'"></span></div></div>
    <form @submit.prevent="submit()" class="space-y-5 p-5 sm:p-7">
        <p x-show="error" x-text="error" role="alert" class="rounded-xl bg-red-50 p-4 text-sm text-red-700"></p><p x-show="message" x-text="message" role="status" aria-live="polite" class="rounded-xl bg-brand-50 p-4 text-sm text-brand-700"></p>
        <fieldset :disabled="loading||saving" class="space-y-5 disabled:opacity-50"><legend class="sr-only">Isi laporan kerja harian</legend>
            <div><p class="mb-3 text-sm font-semibold text-slate-700">Total durasi hari ini</p><div class="grid max-w-md grid-cols-2 gap-3"><label for="report-hours" class="text-xs font-semibold text-slate-500">Jam<input id="report-hours" type="number" min="0" max="144" step="1" required x-model.number="hours" class="mt-2 min-h-[48px] w-full rounded-xl border border-slate-200 px-4 text-lg font-semibold text-slate-900"></label><label for="report-minutes" class="text-xs font-semibold text-slate-500">Menit<input id="report-minutes" type="number" min="0" max="59" step="1" required x-model.number="minutes" class="mt-2 min-h-[48px] w-full rounded-xl border border-slate-200 px-4 text-lg font-semibold text-slate-900"></label></div><p class="mt-3 text-xs text-slate-500">Contoh: 2 jam 30 menit. Jika memakai beberapa HP, isi total durasinya.</p></div>
            <fieldset><legend class="mb-3 text-sm font-semibold text-slate-700">HP yang dipakai <span class="font-normal text-slate-400">· bisa pilih lebih dari satu</span></legend><div class="grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="(label,key) in options" :key="key"><label :class="phones.includes(key)?'border-brand-500 bg-brand-50':'border-slate-200 hover:bg-slate-50'" class="flex min-h-[56px] cursor-pointer items-center gap-3 rounded-xl border px-4 transition"><input type="checkbox" :value="key" x-model="phones" class="h-4 w-4 accent-emerald-600"><span class="text-sm font-semibold" x-text="label"></span></label></template></div></fieldset>
        </fieldset>
        <div class="flex flex-col justify-between gap-4 border-t border-slate-100 pt-5 sm:flex-row sm:items-center"><p class="text-xs text-slate-500" x-text="dirty?'Ada perubahan belum dikirim.':'Satu laporan per hari. Laporan hari ini masih bisa diperbarui.'"></p><div class="flex flex-wrap gap-2"><button type="button" @click="reload()" :disabled="saving||loading" class="min-h-[44px] rounded-lg border border-slate-200 px-4 text-xs font-semibold text-slate-600">Muat ulang</button><button type="submit" :disabled="saving||loading||totalMinutes<1||!phones.length||!dirty" class="min-h-[44px] rounded-lg bg-brand-600 px-5 text-sm font-bold text-white hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-40" x-text="saving?'Mengirim…':(revision?'Perbarui laporan':'Kirim laporan')"></button></div></div>
    </form>
    <div class="border-t border-slate-100 p-5 sm:p-7"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><h3 class="font-bold text-slate-800">Riwayat laporanmu</h3><label><span class="sr-only">Bulan riwayat laporan</span><input type="month" x-model="month" @change="load(false)" :disabled="loading||saving" class="h-11 rounded-lg border border-slate-200 px-3 text-sm"></label></div><div class="space-y-3"><template x-for="report in reports" :key="report.id"><article class="flex flex-col justify-between gap-2 rounded-xl bg-slate-50 p-4 sm:flex-row"><div><p class="text-sm font-semibold" x-text="dateLabel(report.work_date)"></p><p class="mt-1 text-xs text-slate-500" x-text="'HP: '+phoneNames(report.phones)"></p></div><p class="text-sm font-bold text-brand-700" x-text="duration(report.total_duration_minutes)"></p></article></template><p x-show="!loading&&!reports.length" class="py-4 text-center text-sm text-slate-500">Belum ada laporan pada bulan ini.</p></div></div>
</section>
